// Frieren's TranscriptImage resolver: a tool-result `src` is a Volume path (the
// agent offloads generated bytes to /pictures, #194); the browser reads it from
// the local synced replica and hands the Transcript an object URL. The DO's write
// reaches the replica via the capability socket's dirty-push flush, which can lag
// a beat behind the tool result — hence the brief retry.
import type { TranscriptImage } from '@justfiles/ui/Transcript'
import { openProfile } from '../fs'

const cache = new Map<string, Promise<string | null>>()

export function resolveTranscriptImage(image: TranscriptImage): Promise<string | null> {
	const cached = cache.get(image.src)
	if (cached) return cached
	const load = (async () => {
		const volume = await openProfile()
		for (let attempt = 0; attempt < 10; attempt++) {
			try {
				const bytes = await volume.readFile(image.src)
				return URL.createObjectURL(new Blob([bytes as BlobPart], { type: image.mimeType }))
			} catch {
				// Not replicated yet — force a sync cycle rather than waiting out the
				// regular interval, then give the pull a moment to land.
				await volume.flush().catch(() => {})
				await new Promise((resolve) => setTimeout(resolve, 1500))
			}
		}
		return null
	})()
	cache.set(image.src, load)
	// A miss is not cached: the bytes may simply not have synced yet, and a later
	// render should get another chance.
	void load.then((url) => {
		if (url === null) cache.delete(image.src)
	})
	return load
}
